const lessons = [
  {
    title: 'Mindset 0 Unit 4-5',
    description: 'Travel and Holidays · Food and Eating Habits — từ vựng & cụm từ tự nhiên hay dùng trong IELTS Speaking/Writing',
    difficulty: 'B1',
    order: 6,
    words: dedupeWords([...unit4, ...unit5]),
  },
  {
    title: 'Mindset 0 Unit 6-7',
    description: 'Transport and Places in Town · Health and Fitness — từ vựng & cụm từ tự nhiên hay dùng trong IELTS Speaking/Writing',
    difficulty: 'B1',
    order: 7,
    words: dedupeWords([...unit6, ...unit7]),
  },
  {
    title: 'Mindset 0 Unit 8-9',
    description: 'Education and Learning · Career and Jobs — từ vựng & cụm từ tự nhiên hay dùng trong IELTS Speaking/Writing',
    difficulty: 'B1',
    order: 8,
    words: dedupeWords([...unit8, ...unit9]),
  },
  {
    // Standalone — Unit 11 (to pair with per the 2-units-per-lesson
    // convention) hasn't been compiled yet; add it here and rename to
    // "Mindset 0 Unit 10-11" once it is.
    title: 'Mindset 0 Unit 10',
    description: 'Technology — từ vựng & cụm từ tự nhiên hay dùng trong IELTS Speaking/Writing',
    difficulty: 'B1',
    order: 9,
    words: dedupeWords(unit10),
  },
];

function toWordDoc([word, meaning, example, definition]) {
  return { word, meaning, example, definition, ipa: '', partOfSpeech: '', collocations: [], distractors: [] };
}

// A handful of general phrases (e.g. "qualification", "be good at") recur
// across adjacent units' own source lists — drop later repeats so a single
// lesson never quizzes the same word twice.
function dedupeWords(entries) {
  const seen = new Set();
  return entries.filter(([word]) => {
    const key = word.trim().toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

async function runSeed() {
  const VocabularyLesson = require('../models/VocabularyLesson');
  const User = require('../models/User');

  const admin = await User.findOne({ email: ADMIN_EMAIL }).select('_id').lean();
  if (!admin) throw new Error(`Admin user not found: ${ADMIN_EMAIL}`);

  for (const lesson of lessons) {
    const existing = await VocabularyLesson.findOne({ title: lesson.title }).lean();
    if (existing) {
      console.log(`[SeedVocabMindset0] "${lesson.title}" already exists (_id=${existing._id}) – skip`);
      continue;
    }
    const doc = await VocabularyLesson.create({
      title: lesson.title,
      description: lesson.description,
      difficulty: lesson.difficulty,
      order: lesson.order,
      targetClass: '',
      published: false, // review before publishing to students
      createdBy: admin._id,
      words: lesson.words.map(toWordDoc),
    });
    console.log(`[SeedVocabMindset0] Inserted "${doc.title}" (_id=${doc._id}, ${doc.words.length} words)`);
  }
}

if (require.main === module) {
  require('dotenv').config();
  const mongoose = require('mongoose');
  (async () => {
    await mongoose.connect(process.env.MONGO_URI);
    try {
      await runSeed();
    } finally {
      await mongoose.disconnect();
    }
  })().catch(e => { console.error('[SeedVocabMindset0] FAILED', e); process.exit(1); });
}

module.exports = { runSeed, lessons };
